`,r:{minutes:.03,words:9},t:"v8垃圾回收机制",y:"a"}}],["/JAVASCRIPT/%E4%B8%80%E6%AC%A1%E6%B8%B2%E6%9F%9310w%E6%9D%A1%E6%95%B0%E6%8D%AE.html",{loader:()=>A(()=>import("./一次渲染10w条数据.html-DZTznbNK.js"),__vite__mapDeps([132,1])),meta:{d:1723009479e3,e:`
